import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
    const R = camera.limits.planetRadius;
    const lat = (latitudeDeg * Math.PI) / 180;
    const lon = (longitudeDeg * Math.PI) / 180;
    camera.center = {
        x: R * Math.cos(lat) * Math.cos(lon),
        y: -R * Math.cos(lat) * Math.sin(lon),
        z: R * Math.sin(lat),
    };
}
```

I wrote `src/center-on.ts` which computes the surface point from latitude/longitude using the coordinate system documented in the notes (north = +Z, east = −Y at the prime meridian, so the standard spherical mapping with a sign flip on the Y axis) and assigns a fresh object to `camera.center` so the camera re-orbits immediately per note 11. I'm confident in the geometry; the only minor uncertainty is whether `Vec3` might have additional required fields beyond `x`/`y`/`z` in the actual runtime type, but nothing in the provided declarations suggests it does.
